+import { v4 as uuid } from 'uuid'
+import { getDb } from './index.js'
+
+const now = () => new Date().toISOString()
+
+export const getBoard = (req, res) => {
+  try {
+    const db = getDb()
+    const board = db.prepare(`
+      SELECT id, owner_id, name, viewport, background_color, created_at, updated_at
+      FROM boards WHERE id = ?
+    `).get(req.params.boardId)
+    if (!board) {
+      return res.status(404).json({ error: 'Board not found' })
+    }
+    const cards = db.prepare(`
+      SELECT * FROM cards WHERE board_id = ? ORDER BY z_index
+    `).all(req.params.boardId)
+    const parsedCards = cards.map(c => ({
+      ...c,
+      geometry: JSON.parse(c.geometry),
+      appearance: JSON.parse(c.appearance),
+      metadata: JSON.parse(c.metadata),
+      content_items: JSON.parse(c.content_items),
+      archived: !!c.archived,
+    }))
+    res.json({ ...board, taskCards: parsedCards, schemaVersion: 1 })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const createBoard = (req, res) => {
+  try {
+    const db = getDb()
+    const id = uuid()
+    const name = req.body.name || 'تخته بدون عنوان'
+    const viewport = req.body.viewport || { x: 0, y: 0, zoom: 1 }
+    const backgroundColor = req.body.background_color || '#F7F6F2'
+    const createdAt = now()
+    const updatedAt = now()
+    db.prepare(`
+      INSERT INTO boards (id, name, viewport, background_color, created_at, updated_at)
+      VALUES (?, ?, ?, ?, ?, ?)
+    `).run(id, name, JSON.stringify(viewport), backgroundColor, createdAt, updatedAt)
+    res.status(201).json({ id, name, viewport, background_color: backgroundColor, created_at: createdAt, updated_at: updatedAt })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const updateBoard = (req, res) => {
+  try {
+    const db = getDb()
+    const { name, viewport, background_color } = req.body
+    const updates = []
+    const values = []
+    if (name !== undefined) { updates.push('name = ?'); values.push(name) }
+    if (viewport !== undefined) { updates.push('viewport = ?'); values.push(JSON.stringify(viewport)) }
+    if (background_color !== undefined) { updates.push('background_color = ?'); values.push(background_color) }
+    updates.push('updated_at = ?')
+    values.push(now())
+    values.push(req.params.boardId)
+    const result = db.prepare(`UPDATE boards SET ${updates.join(', ')} WHERE id = ?`).run(...values)
+    if (result.changes === 0) {
+      return res.status(404).json({ error: 'Board not found' })
+    }
+    res.json({ message: 'Board updated' })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const deleteBoard = (req, res) => {
+  try {
+    const db = getDb()
+    const result = db.prepare('DELETE FROM boards WHERE id = ?').run(req.params.boardId)
+    if (result.changes === 0) {
+      return res.status(404).json({ error: 'Board not found' })
+    }
+    res.json({ message: 'Board deleted' })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const listBoards = (req, res) => {
+  try {
+    const db = getDb()
+    const boards = db.prepare('SELECT * FROM boards ORDER BY updated_at DESC').all()
+    const result = boards.map(b => ({
+      ...b,
+      viewport: JSON.parse(b.viewport),
+      archived: undefined,
+      created_at: b.created_at,
+      updated_at: b.updated_at,
+    }))
+    res.json(result)
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const importBoard = (req, res) => {
+  try {
+    const db = getDb()
+    const { boardId, data } = req.body
+    if (!data || !data.taskCards) {
+      return res.status(400).json({ error: 'Invalid board data' })
+    }
+    const boardData = data.board || {}
+    const boardIdToUse = boardId || uuid()
+    const nowStr = now()
+    const stmt = db.prepare(`
+      INSERT INTO boards (id, name, viewport, background_color, created_at, updated_at)
+      VALUES (?, ?, ?, ?, ?, ?)
+      ON CONFLICT(id) DO UPDATE SET name=excluded.name, viewport=excluded.viewport, background_color=excluded.background_color, updated_at=excluded.updated_at
+    `)
+    stmt.run(
+      boardIdToUse,
+      boardData.name || 'تخته',
+      JSON.stringify(boardData.viewport || { x: 0, y: 0, zoom: 1 }),
+      boardData.background_color || '#F7F6F2',
+      boardData.createdAt || nowStr,
+      nowStr
+    )
+    for (const card of data.taskCards) {
+      db.prepare(`
+        INSERT INTO cards (id, board_id, geometry, z_index, appearance, metadata, content_items, archived, created_at, updated_at)
+        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+      `).run(
+        card.id, boardIdToUse,
+        JSON.stringify(card.geometry || { x: 0, y: 0, width: 300, height: 220, rotation: 0 }),
+        card.zIndex || 0,
+        JSON.stringify(card.appearance || { shapeType: 'roundedRectangle', fill: '#FFF4B8', stroke: '#222222', strokeWidth: 1.5, opacity: 1, borderRadius: 14 }),
+        JSON.stringify(card.metadata || { title: '', description: '' }),
+        JSON.stringify(card.contentItems || []),
+        card.archived ? 1 : 0,
+        card.createdAt || nowStr,
+        card.updatedAt || nowStr
+      )
+    }
+    res.json({ boardId: boardIdToUse, migrated: true, message: 'Board imported' })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}

