+import { v4 as uuid } from 'uuid'
+import { getDb } from '../db/index.js'
+
+const now = () => new Date().toISOString()
+
+export const createCard = (req, res) => {
+  try {
+    const db = getDb()
+    const { boardId } = req.params
+    const card = req.body
+    const id = uuid()
+    const createdAt = now()
+    const updatedAt = now()
+    db.prepare(`
+      INSERT INTO cards (id, board_id, geometry, z_index, appearance, metadata, content_items, archived, created_at, updated_at)
+      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+    `).run(
+      id, boardId,
+      JSON.stringify(card.geometry || { x: 0, y: 0, width: 300, height: 220, rotation: 0 }),
+      card.zIndex || 0,
+      JSON.stringify(card.appearance || { shapeType: 'roundedRectangle', fill: '#FFF4B8', stroke: '#222222', strokeWidth: 1.5, opacity: 1, borderRadius: 14 }),
+      JSON.stringify(card.metadata || { title: '', description: '' }),
+      JSON.stringify(card.contentItems || []),
+      card.archived ? 1 : 0,
+      createdAt,
+      updatedAt
+    )
+    const result = db.prepare('SELECT * FROM cards WHERE id = ?').get(id)
+    res.status(201).json(formatCard(result))
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const getCard = (req, res) => {
+  try {
+    const db = getDb()
+    const card = db.prepare('SELECT * FROM cards WHERE id = ? AND board_id = ?').get(req.params.cardId, req.params.boardId)
+    if (!card) {
+      return res.status(404).json({ error: 'Card not found' })
+    }
+    res.json(formatCard(card))
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const updateCard = (req, res) => {
+  try {
+    const db = getDb()
+    const { boardId, cardId } = req.params
+    const updates = req.body
+    const fields = []
+    const values = []
+    if (updates.geometry !== undefined) { fields.push('geometry = ?'); values.push(JSON.stringify(updates.geometry)) }
+    if (updates.zIndex !== undefined) { fields.push('z_index = ?'); values.push(updates.zIndex) }
+    if (updates.appearance !== undefined) { fields.push('appearance = ?'); values.push(JSON.stringify(updates.appearance)) }
+    if (updates.metadata !== undefined) { fields.push('metadata = ?'); values.push(JSON.stringify(updates.metadata)) }
+    if (updates.contentItems !== undefined) { fields.push('content_items = ?'); values.push(JSON.stringify(updates.contentItems)) }
+    if (updates.archived !== undefined) { fields.push('archived = ?'); values.push(updates.archived ? 1 : 0) }
+    fields.push('updated_at = ?')
+    values.push(now())
+    values.push(cardId, boardId)
+    const result = db.prepare(`UPDATE cards SET ${fields.join(', ')} WHERE id = ? AND board_id = ?`).run(...values)
+    if (result.changes === 0) {
+      return res.status(404).json({ error: 'Card not found' })
+    }
+    const card = db.prepare('SELECT * FROM cards WHERE id = ?').get(cardId)
+    res.json(formatCard(card))
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const deleteCard = (req, res) => {
+  try {
+    const db = getDb()
+    const result = db.prepare('DELETE FROM cards WHERE id = ? AND board_id = ?').run(req.params.cardId, req.params.boardId)
+    if (result.changes === 0) {
+      return res.status(404).json({ error: 'Card not found' })
+    }
+    res.json({ message: 'Card deleted' })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const archiveCard = (req, res) => {
+  try {
+    const db = getDb()
+    const result = db.prepare('UPDATE cards SET archived = 1, updated_at = ? WHERE id = ? AND board_id = ?').run(now(), req.params.cardId, req.params.boardId)
+    if (result.changes === 0) {
+      return res.status(404).json({ error: 'Card not found' })
+    }
+    res.json({ message: 'Card archived' })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const restoreCard = (req, res) => {
+  try {
+    const db = getDb()
+    const result = db.prepare('UPDATE cards SET archived = 0, updated_at = ? WHERE id = ? AND board_id = ?').run(now(), req.params.cardId, req.params.boardId)
+    if (result.changes === 0) {
+      return res.status(404).json({ error: 'Card not found' })
+    }
+    res.json({ message: 'Card restored' })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const listCards = (req, res) => {
+  try {
+    const db = getDb()
+    const cards = db.prepare('SELECT * FROM cards WHERE board_id = ? ORDER BY z_index').all(req.params.boardId)
+    res.json(cards.map(formatCard))
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+function formatCard(card) {
+  return {
+    ...card,
+    geometry: JSON.parse(card.geometry),
+    appearance: JSON.parse(card.appearance),
+    metadata: JSON.parse(card.metadata),
+    content_items: JSON.parse(card.content_items),
+    archived: !!card.archived,
+  }
+}

