+import { getDb, getUploadDir } from '../db/index.js'
+import { v4 as uuid } from 'uuid'
+import fs from 'node:fs'
+import path from 'node:path'
+
+const now = () => new Date().toISOString()
+
+export const uploadMedia = (req, res) => {
+  try {
+    if (!req.file) {
+      return res.status(400).json({ error: 'No file uploaded' })
+    }
+    const db = getDb()
+    const id = uuid()
+    const filename = req.file.originalname || req.file.filename || 'image'
+    const filePath = req.file.path
+    const stat = fs.statSync(filePath)
+    const record = {
+      id,
+      board_id: req.body.boardId || req.params.boardId,
+      filename,
+      path: filePath,
+      mime_type: req.file.mimetype || 'application/octet-stream',
+      alt: req.body.alt || filename,
+      size: stat.size,
+      created_at: now(),
+    }
+    db.prepare(`
+      INSERT INTO media (id, board_id, filename, path, mime_type, alt, size, created_at)
+      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
+    `).run(id, record.board_id, filename, filePath, record.mime_type, record.alt, record.size, record.created_at)
+    res.status(201).json({ id, filename, path: filePath, alt: record.alt, mime_type: record.mime_type, size: record.size })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const getMedia = (req, res) => {
+  try {
+    const db = getDb()
+    const media = db.prepare('SELECT * FROM media WHERE id = ?').get(req.params.mediaId)
+    if (!media) {
+      return res.status(404).json({ error: 'Media not found' })
+    }
+    if (!fs.existsSync(media.path)) {
+      return res.status(404).json({ error: 'Media file not found on disk' })
+    }
+    res.sendFile(path.resolve(media.path))
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const deleteMedia = (req, res) => {
+  try {
+    const db = getDb()
+    const media = db.prepare('SELECT * FROM media WHERE id = ?').get(req.params.mediaId)
+    if (!media) {
+      return res.status(404).json({ error: 'Media not found' })
+    }
+    if (fs.existsSync(media.path)) {
+      fs.unlinkSync(media.path)
+    }
+    db.prepare('DELETE FROM media WHERE id = ?').run(req.params.mediaId)
+    res.json({ message: 'Media deleted' })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const listMedia = (req, res) => {
+  try {
+    const db = getDb()
+    const { boardId } = req.query
+    if (!boardId) {
+      return res.status(400).json({ error: 'boardId query parameter required' })
+    }
+    const media = db.prepare('SELECT * FROM media WHERE board_id = ?').all(boardId)
+    res.json(media)
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}
+
+export const clearUnusedMedia = (req, res) => {
+  try {
+    const db = getDb()
+    const usedIds = new Set(req.body.usedIds || [])
+    const allMedia = db.prepare('SELECT * FROM media').all()
+    const orphaned = allMedia.filter(m => !usedIds.has(m.id))
+    for (const media of orphaned) {
+      try {
+        if (fs.existsSync(media.path)) {
+          fs.unlinkSync(media.path)
+        }
+        db.prepare('DELETE FROM media WHERE id = ?').run(media.id)
+      } catch {
+        // ignore individual failures
+      }
+    }
+    res.json({ deleted: orphaned.length, orphanedIds: orphaned.map(m => m.id) })
+  } catch (err) {
+    res.status(500).json({ error: err.message })
+  }
+}

