@@ -1,793 +1,856 @@
 import { useState, useEffect, useRef, useCallback } from 'react';
 import type {
   TaskCard, ContentItem, TextItem, ImageItem, ShapeItem,
   BoardState, HistorySnapshot, HistoryLogEntry,
   Selection, ToastMessage, ResizeHandle, Geometry,
 } from './types';
-import { uuid, now, deepClone, compressImage, formatTimestamp } from './utils';
-import { loadState, saveState, exportJson, validateImport } from './persistence';
+import { uuid, now, deepClone, formatTimestamp } from './utils';
+import { fetchBoard, createBoard, updateBoard, deleteBoard, listBoards, importBoard, exportBoard } from './api';
+import { saveMedia, getMedia, deleteMedia } from './mediaService';
 import TaskCardView from './components/TaskCardView';
 import InspectorPanel from './components/InspectorPanel';
 import Toolbar from './components/Toolbar';

 // ─── constants ──────────────────────────────────────────────────────────────
 const MAX_HISTORY = 50;
 const CARD_COLORS = ['#FFF4B8', '#B8E4FF', '#FFD4D4', '#D4F5D4', '#E8D4FF', '#FFD9B8'];
 let _colorIdx = 0;
 const pickColor = () => CARD_COLORS[_colorIdx++ % CARD_COLORS.length];

 // ─── drag state ──────────────────────────────────────────────────────────────
 type DragOp =
   | { kind: 'none' }
   | { kind: 'pan'; startPtr: [number, number]; startVp: [number, number] }
   | { kind: 'move-card'; cardId: string; startPtr: [number, number]; startCard: [number, number] }
   | { kind: 'move-content'; cardId: string; contentId: string; startPtr: [number, number]; startContent: [number, number] }
   | { kind: 'resize-card'; cardId: string; handle: ResizeHandle; startPtr: [number, number]; startGeom: Geometry }
   | { kind: 'resize-content'; cardId: string; contentId: string; handle: ResizeHandle; startPtr: [number, number]; startGeom: Geometry }
   | { kind: 'rotate-card'; cardId: string; centerScreen: [number, number]; startAngle: number; startRotation: number };

 // ─── geometry helpers ────────────────────────────────────────────────────────
 function applyCardResize(startGeom: Geometry, handle: ResizeHandle, worldDx: number, worldDy: number): Geometry {
   const { rotation } = startGeom;
   const rad = (rotation * Math.PI) / 180;
   const cosR = Math.cos(rad);
   const sinR = Math.sin(rad);

   // Convert world delta → card-local delta (rotate by -rotation)
   const lx = cosR * worldDx + sinR * worldDy;
   const ly = -sinR * worldDx + cosR * worldDy;

   const { width, height } = startGeom;
   let newW = width, newH = height;

   switch (handle) {
     case 'se': newW = Math.max(60, width + lx); newH = Math.max(60, height + ly); break;
     case 'nw': newW = Math.max(60, width - lx); newH = Math.max(60, height - ly); break;
     case 'ne': newW = Math.max(60, width + lx); newH = Math.max(60, height - ly); break;
     case 'sw': newW = Math.max(60, width - lx); newH = Math.max(60, height + ly); break;
     case 'e':  newW = Math.max(60, width + lx); break;
     case 'w':  newW = Math.max(60, width - lx); break;
     case 's':  newH = Math.max(60, height + ly); break;
     case 'n':  newH = Math.max(60, height - ly); break;
   }

   // Center shift in card-local space (keeps the opposite corner fixed)
   let localCx = 0, localCy = 0;
   switch (handle) {
     case 'se': localCx = (newW - width) / 2;  localCy = (newH - height) / 2;  break;
     case 'nw': localCx = -(newW - width) / 2; localCy = -(newH - height) / 2; break;
     case 'ne': localCx = (newW - width) / 2;  localCy = -(newH - height) / 2; break;
     case 'sw': localCx = -(newW - width) / 2; localCy = (newH - height) / 2;  break;
     case 'e':  localCx = (newW - width) / 2;  break;
     case 'w':  localCx = -(newW - width) / 2; break;
     case 's':  localCy = (newH - height) / 2; break;
     case 'n':  localCy = -(newH - height) / 2; break;
   }

   // Rotate center shift back to world space
   const worldCx = cosR * localCx - sinR * localCy;
   const worldCy = sinR * localCx + cosR * localCy;

   const newCenterX = startGeom.x + width / 2 + worldCx;
   const newCenterY = startGeom.y + height / 2 + worldCy;

   return { x: newCenterX - newW / 2, y: newCenterY - newH / 2, width: newW, height: newH, rotation };
 }

 function applyContentResize(startGeom: Geometry, handle: ResizeHandle, dx: number, dy: number): Geometry {
   let { x, y, width, height, rotation } = startGeom;
   switch (handle) {
     case 'se': width = Math.max(20, width + dx); height = Math.max(20, height + dy); break;
     case 'nw': x += dx; y += dy; width = Math.max(20, width - dx); height = Math.max(20, height - dy); break;
     case 'ne': y += dy; width = Math.max(20, width + dx); height = Math.max(20, height - dy); break;
     case 'sw': x += dx; width = Math.max(20, width - dx); height = Math.max(20, height + dy); break;
     case 'e':  width = Math.max(20, width + dx); break;
     case 'w':  x += dx; width = Math.max(20, width - dx); break;
     case 's':  height = Math.max(20, height + dy); break;
     case 'n':  y += dy; height = Math.max(20, height - dy); break;
   }
   return { x, y, width, height, rotation };
 }

