+const API_BASE = import.meta.env.VITE_API_URL || '/api'
+
+export interface BoardData {
+  id: string
+  owner_id: string
+  name: string
+  viewport: { x: number; y: number; zoom: number }
+  background_color: string
+  created_at: string
+  updated_at: string
+}
+
+export interface BoardState {
+  schemaVersion: 1
+  board: BoardData
+  taskCards: any[]
+}
+
+export async function fetchBoard(boardId: string): Promise<BoardState | null> {
+  try {
+    const res = await fetch(`${API_BASE}/boards/${boardId}`)
+    if (!res.ok) return null
+    return res.json()
+  } catch {
+    return null
+  }
+}
+
+export async function createBoard(name?: string): Promise<BoardState | null> {
+  try {
+    const res = await fetch(`${API_BASE}/boards`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ name }),
+    })
+    if (!res.ok) return null
+    return res.json()
+  } catch {
+    return null
+  }
+}
+
+export async function updateBoard(boardId: string, updates: Record<string, any>): Promise<boolean> {
+  try {
+    const res = await fetch(`${API_BASE}/boards/${boardId}`, {
+      method: 'PUT',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify(updates),
+    })
+    return res.ok
+  } catch {
+    return false
+  }
+}
+
+export async function deleteBoard(boardId: string): Promise<boolean> {
+  try {
+    const res = await fetch(`${API_BASE}/boards/${boardId}`, { method: 'DELETE' })
+    return res.ok
+  } catch {
+    return false
+  }
+}
+
+export async function listBoards(): Promise<BoardData[]> {
+  try {
+    const res = await fetch(`${API_BASE}/boards`)
+    if (!res.ok) return []
+    return res.json()
+  } catch {
+    return []
+  }
+}
+
+export async function importBoard(data: any): Promise<{ boardId: string; migrated: boolean } | null> {
+  try {
+    const res = await fetch(`${API_BASE}/boards/import`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify(data),
+    })
+    if (!res.ok) return null
+    return res.json()
+  } catch {
+    return null
+  }
+}
+
+export async function exportBoard(state: BoardState): Promise<void> {
+  const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' })
+  const url = URL.createObjectURL(blob)
+  const a = document.createElement('a')
+  a.href = url
+  a.download = `visual-board-${new Date().toISOString().slice(0, 10)}.json`
+  a.click()
+  URL.revokeObjectURL(url)
+}

