+const API_BASE = import.meta.env.VITE_API_URL || '/api'
+
+export interface MediaRecord {
+  id: string
+  blob: Blob
+  kind: 'image'
+  alt: string
+  createdAt: string
+}
+
+let cachedAuthToken: string | null = null
+
+export function setAuthToken(token: string | null) {
+  cachedAuthToken = token
+}
+
+function getHeaders(): HeadersInit {
+  const headers: Record<string, string> = { 'Content-Type': 'application/json' }
+  if (cachedAuthToken) {
+    headers['Authorization'] = `Bearer ${cachedAuthToken}`
+  }
+  return headers
+}
+
+export async function saveMedia(blob: Blob, alt: string): Promise<string> {
+  try {
+    const formData = new FormData()
+    formData.append('file', blob, alt)
+    formData.append('alt', alt)
+    const res = await fetch(`${API_BASE}/media`, {
+      method: 'POST',
+      headers: { 'Authorization': `Bearer ${cachedAuthToken || ''}` },
+      body: formData,
+    })
+    if (!res.ok) throw new Error('Upload failed')
+    const data = await res.json()
+    return data.id
+  } catch {
+    throw new Error('Failed to save media')
+  }
+}
+
+export async function getMedia(id: string): Promise<MediaRecord | null> {
+  try {
+    const res = await fetch(`${API_BASE}/media/${id}`, {
+      headers: getHeaders(),
+    })
+    if (!res.ok) return null
+    const blob = await res.blob()
+    return { id, blob, kind: 'image', alt: '', createdAt: new Date().toISOString() }
+  } catch {
+    return null
+  }
+}
+
+export async function deleteMedia(id: string): Promise<void> {
+  try {
+    await fetch(`${API_BASE}/media/${id}`, {
+      method: 'DELETE',
+      headers: getHeaders(),
+    })
+  } catch {
+    // ignore
+  }
+}
+
+export async function clearUnusedMedia(usedIds: Set<string>): Promise<string[]> {
+  try {
+    const res = await fetch(`${API_BASE}/media/clear-unused`, {
+      method: 'POST',
+      headers: { ...getHeaders(), 'Content-Type': 'application/json' },
+      body: JSON.stringify({ usedIds: Array.from(usedIds) }),
+    })
+    if (!res.ok) return []
+    const data = await res.json()
+    return data.orphanedIds || []
+  } catch {
+    return []
+  }
+}
+
+export async function listAllMediaIds(): Promise<string[]> {
+  try {
+    const res = await fetch(`${API_BASE}/media`, { headers: getHeaders() })
+    if (!res.ok) return []
+    const media = await res.json()
+    return media.map((m: any) => m.id)
+  } catch {
+    return []
+  }
+}
+
+export async function clearAllMedia(): Promise<void> {
+  try {
+    await fetch(`${API_BASE}/media`, { method: 'DELETE', headers: getHeaders() })
+  } catch {
+    // ignore
+  }
+}

